// BHD-70 – treść instrukcji (okno pod przyciskiem „?” i w menu Pomoc).
// Wygląd okna jest wspólny dla serii: ~/Developer/shared/BHStyle/Help.swift.
//
// Każda nowa funkcja = dopisek tutaj, od razu po polsku i po angielsku.

import Foundation

enum HelpContent {
    static var doc: HelpDoc {
        HelpDoc(
            title: "BHD-70",
            lead: tr("Super LA Synthesizer – dopracowana rekreacja instrumentu Roland D-70 w oparciu o oryginalne oprogramowanie z Twojego własnego egzemplarza. Nie przybliżenie i nie model: dźwięk liczy ten sam program, który chodzi w sprzęcie. Panel jest przepisany co do punktu z prawdziwego D-70, tylko w kolorach serii BH. Działa jako wtyczka AUv3 w DAW-ie i jako osobny program na Maca. Samego oprogramowania Rolanda BHD-70 nie zawiera – prosi o zgranie z Twojego instrumentu przy pierwszym uruchomieniu.",
                     "Super LA Synthesizer – a careful recreation of the Roland D-70, running the original software from your own unit. Not an approximation and not a model: the sound is computed by the very program that runs in the hardware. The panel is laid out point for point like a real D-70, only in the BH series colours. It works as an AUv3 plug-in in a DAW and as a standalone Mac app. BHD-70 contains none of Roland's software itself – it asks for a dump from your instrument on first start."),
            sections: [
                HelpSection(title: tr("Czego instrument potrzebuje od Ciebie", "What the instrument needs from you"), items: [
                    .note(tr("BHD-70 **nie zawiera oprogramowania Rolanda** i zawierać go nie może – firmware D-70 i jego brzmienia są własnością Rolanda. Instrument jest dla tych, którzy mają własny D-70: przy pierwszym uruchomieniu prosi o zgranie z własnego egzemplarza, sprawdza je i zapamiętuje. Potem już nigdy o to nie pyta.",
                             "BHD-70 **does not contain any Roland software** and cannot: the D-70 firmware and its sounds belong to Roland. The instrument is for people who own a D-70: on first start it asks for a dump from your own unit, checks it and remembers it. It never asks again.")),
                    .bullet(tr("**Firmware – dwa pliki po 65 536 bajtów.** Zgranie kości EPROM z płyty głównej: parzystej (IC4) i nieparzystej (IC9). Wystarczy jedna wersja. Najlepiej **1.19** (z 9 marca 1993, najnowsza, jaka powstała), ale program przyjmie też 1.16, 1.14, 1.12 albo 1.10. Wersji 1.00 nikt nigdy nie zgrał.",
                               "**Firmware – two files of 65,536 bytes each.** Dumps of the EPROMs on the main board: even (IC4) and odd (IC9). One version is enough. **1.19** is best (9 March 1993, the last one made), but 1.16, 1.14, 1.12 and 1.10 are accepted too. Version 1.00 has never been dumped.")),
                    .bullet(tr("**Fale – sześć plików po 524 288 bajtów**, razem 3 MB. To kości z brzmieniami PCM, oznaczone A, B, C, D, E i F. Potrzebne są wszystkie sześć. Istnieje tylko jedna ich wersja – Roland ich nigdy nie zmieniał.",
                               "**Waves – six files of 524,288 bytes each**, 3 MB in all. These are the PCM wave chips, marked A, B, C, D, E and F. All six are needed. There is only one version of them – Roland never changed them.")),
                    .bullet(tr("**Brzmienia.** Instrument wstaje z **pustą pamięcią** – dokładnie jak sprzęt po wyjęciu baterii: gra, ale nazwy brzmień to śmieci. Brzmienia trzeba do niego wgrać samemu, tak samo jak do sprzętu. Jak – w rozdziale „Jak wgrać brzmienia”.",
                               "**Sounds.** The instrument starts with **empty memory** – exactly like the hardware with a flat battery: it plays, but the patch names are garbage. You load the sounds yourself, just as you would into the hardware. How – see \"Loading your sounds\".")),
                    .note(tr("**Nazwy plików nie mają znaczenia.** Rozpoznaję je po zawartości: sprawdzam rozmiar i sumę kontrolną każdego pliku. Możesz je nazwać jak chcesz i porozrzucać po podfolderach – wskaż folder, a resztę zrobię sam. Jeśli plik nie pasuje, po prostu go pomijam i mówię, czego brakuje.",
                             "**File names do not matter.** I recognise them by content: I check each file's size and checksum. Name them as you like and scatter them across subfolders – point me at the folder and I do the rest. A file that does not match is simply skipped, and I tell you what is still missing.")),
                    .bullet(tr("**Kości** wyjmuje się z instrumentu i odczytuje programatorem EPROM – robi to serwis albo ktoś, kto ma sprzęt do programowania kości.",
                               "**The chips** are taken out of the instrument and read with an EPROM programmer – a service shop does this, or anyone with chip-reading equipment.")),
                    .bullet(tr("**Brzmienia** zgrywasz ze swojego D-70 kablem MIDI do pliku .syx, bez rozkręcania czegokolwiek, i wgrywasz je przyciskiem **SYSEX** na panelu – patrz rozdział „Jak wgrać brzmienia”.",
                               "**The sounds** you dump from your own D-70 over a MIDI cable into a .syx file, without opening anything, and load them with the **SYSEX** button on the panel – see \"Loading your sounds\".")),
                    .note(tr("Pliki, które wskażesz, zostają na Twoim komputerze – w prywatnym folderze programu. BHD-70 nigdzie ich nie wysyła i nie wkłada ich do siebie.",
                             "The files you point to stay on your computer, in the program's private folder. BHD-70 never sends them anywhere and never bundles them.")),
                ]),
                HelpSection(title: tr("Pierwsze uruchomienie", "The first start"), items: [
                    .step(tr("Otwórz program **BHD-70**. Zamiast panelu zobaczysz okno, które tłumaczy, czego potrzeba. Naciśnij **Wskaż folder z plikami** i pokaż folder ze zgraniem swojego D-70.",
                             "Open the **BHD-70** app. Instead of the panel you get a window explaining what is needed. Press **Choose the folder** and point it at the folder with your D-70 dump.")),
                    .step(tr("Program przejrzy folder razem z podfolderami i wypisze, co rozpoznał i czego jeszcze brakuje. Brakujące pliki możesz dołożyć później – to, co już wskazałeś, zostaje.",
                             "The program scans the folder with its subfolders and lists what it recognised and what is still missing. You can add the missing files later – what you already gave stays.")),
                    .step(tr("Gdy komplet się zgadza, naciśnij **Uruchom instrument**. Instrument wstaje jak sprzęt po włączeniu – to trwa około 20 sekund.",
                             "Once the set is complete, press **Start the instrument**. It boots like the hardware after switching on – that takes about 20 seconds.")),
                    .step(tr("Instrument wstanie z **pustą pamięcią**: zagra, ale w miejscach nazw brzmień zobaczysz śmieci. Tak samo wygląda prawdziwy D-70 po wyjęciu baterii. Brzmienia wgrywa się osobno – patrz rozdział niżej.",
                             "The instrument starts with **empty memory**: it plays, but where the patch names should be you get garbage. A real D-70 looks the same with a flat battery. Loading sounds is a separate step – see the section below.")),
                    .step(tr("**Wtyczka w DAW-ie nie pyta o nic.** Korzysta z tego samego, co program. Jeśli wstawisz ją, zanim wskażesz pliki, powie Ci tylko, żebyś najpierw otworzył program.",
                             "**The plug-in asks for nothing.** It uses the same files as the app. If you insert it before pointing out the files, it just tells you to open the app first.")),
                    .note(tr("Chcesz zacząć od nowa – na przykład wskazać inną wersję firmware'u? W oknie powitalnym jest **Zacznij od nowa**. Kasuje to także pamięć brzmień instrumentu.",
                             "Want to start over – with a different firmware version, say? The welcome window has **Start over**. It also clears the instrument's patch memory.")),
                ]),
                HelpSection(title: tr("Jak wgrać brzmienia", "Loading your sounds"), items: [
                    .note(tr("BHD-70 zachowuje się tu jak prawdziwy instrument: **pamięć brzmień jest pusta, dopóki czegoś do niej nie wgrasz**, a co wgrasz, to zostaje. Podtrzymuje ją dokładnie to samo, co bateryjka w sprzęcie – wgrywa się **raz** i nie trzeba tego powtarzać.",
                             "BHD-70 behaves like the real instrument here: **the patch memory is empty until you put something in it**, and whatever you put in stays. It is kept exactly as a battery keeps it in the hardware – you load it **once** and never repeat it.")),
                    .step(tr("Zgraj brzmienia ze swojego D-70 do pliku: podłącz go do komputera kablem MIDI, włącz nagrywanie w dowolnym programie do SysEx i na D-70 wykonaj **Bulk Dump** (EDIT → System Setup → D.Xfer I→M). Zapisz to jako plik **.syx**. Jeśli masz fabryczną dyskietkę D-70, plik **.mid** z niej też się nada.",
                             "First save the sounds from your D-70 to a file: connect it to the computer with a MIDI cable, start recording in any SysEx utility and run a **Bulk Dump** on the D-70 (EDIT → System Setup → D.Xfer I→M). Save it as a **.syx** file. If you have the factory D-70 disk, the **.mid** file from it works too.")),
                    .step(tr("Na panelu BHD-70, **nad krzyżakiem kursora**, naciśnij **SYSEX**. Otworzy się okno wgrywania.",
                             "On the BHD-70 panel, **above the cursor cross**, press **SYSEX**. The loading window opens.")),
                    .step(tr("Przestaw **blokadę pamięci** w dół, na **OFF**. To ten sam przełącznik, który w prawdziwym D-70 jest z tyłu obudowy: dopóki jest w górze, nic nie nadpisze brzmień.",
                             "Flip **memory protect** down, to **OFF**. It is the same switch that sits on the back of a real D-70: while it is up, nothing can overwrite the sounds.")),
                    .step(tr("Naciśnij **Wskaż plik…** i wskaż swój plik. Zostanie na liście, więc następnym razem wystarczy go kliknąć – a listę widzi i program, i wtyczka w DAW-ie.",
                             "Press **Choose a file…** and point to your file. It stays on the list, so next time you just click it – and both the application and the plug-in see the same list.")),
                    .step(tr("Naciśnij **Wgraj do instrumentu** i nie rób nic przez około minutę. Instrument sam się zgasi, włączy w trybie serwisowym, przyjmie plik i wróci do grania. Przez ten czas nie graj i nie zamykaj okna – wszystko widać na wyświetlaczu.",
                             "Press **Load into the instrument** and leave it alone for about a minute. The instrument powers itself down, comes back up in service mode, takes the file and returns to playing. Do not play and do not close the window meanwhile – you can watch it all on the display.")),
                    .step(tr("Gotowe. Brzmienia siedzą w pamięci i zostają tam także po zamknięciu programu i DAW-a. Blokada pamięci wraca sama na **PROTECT**.",
                             "Done. The sounds are in the memory and stay there after you quit the application and the DAW. Memory protect goes back to **PROTECT** by itself.")),
                    .note(tr("**Co program robi pod spodem.** D-70 nie przyjmuje zgrania pamięci w zwykłym trybie gry – Roland zrobił do tego osobny tryb serwisowy. Instrument trzeba włączyć z przytrzymanym klawiszem **[5]** i wybrać **F.2 Bulk Load All Memory from MIDI**, a potem wysłać plik w tempie kabla MIDI. Dokładnie to robi przycisk SYSEX, tylko bez Twojego udziału.",
                             "**What the program does underneath.** The D-70 does not accept a memory dump in normal play mode – Roland made a separate service mode for it. The instrument has to be powered up with key **[5]** held and **F.2 Bulk Load All Memory from MIDI** chosen, and then the file sent at MIDI cable speed. That is exactly what the SYSEX button does, only without your help.")),
                    .note(tr("Przed każdym wgraniem odkładam kopię dotychczasowej pamięci, a gdy instrument nie potwierdzi odbioru na wyświetlaczu, wysyłka zostaje przerwana i pamięć wraca do poprzedniego stanu. Nie da się więc stracić brzmień przez nieudane wgrywanie.",
                             "Before every load I put aside a copy of the current memory, and if the instrument does not confirm reception on its display the transfer is stopped and the memory goes back to what it was. So a failed load cannot cost you your sounds.")),
                    .note(tr("Przycisk SYSEX przyjmuje **dowolny plik SysEx dla D-70**, nie tylko brzmienia fabryczne – pojedyncze brzmienia, własne zestawy, cokolwiek masz zgrane.",
                             "The SYSEX button takes **any D-70 SysEx file**, not only the factory sounds – single patches, your own sets, whatever you have saved.")),
                ]),
                HelpSection(title: tr("Jak zacząć", "Getting started"), items: [
                    .step(tr("**W DAW-ie** (Logic Pro, Ableton Live, BH AU Host) wstaw instrument **Bronisław Hońca: BHD-70**. Każda wstawiona wtyczka uruchamia własny instrument, więc może ich być tyle, ile zechcesz.",
                             "**In your DAW** (Logic Pro, Ableton Live, BH AU Host) insert the **Bronisław Hońca: BHD-70** instrument. Every instance starts its own instrument, so you can use as many as you like.")),
                    .step(tr("**Bez DAW-a** otwórz program BHD-70. Najpierw zajrzyj do okna **Audio i MIDI** (przycisk w nagłówku albo ⌘,) i wybierz kartę dźwiękową oraz urządzenie MIDI.",
                             "**Without a DAW** open the BHD-70 app. First go to the **Audio and MIDI** window (the button in the header or ⌘,) and pick your audio device and MIDI input.")),
                    .step(tr("Daj instrumentowi **około 20 sekund** na rozruch – pod spodem wstaje prawdziwy D-70 i musi przejść swój rozruch, tak jak sprzęt po włączeniu. Kropka przy nazwie zmieni się wtedy na **gotowy**, a na wyświetlaczu pojawi się nazwa brzmienia.",
                             "Give the instrument **about 20 seconds** to start – a real D-70 is booting underneath and has to go through its power-up, just like the hardware. The dot next to the name then turns to **ready** and the display shows a sound name.")),
                    .step(tr("Graj. Instrument odbiera nuty, kółko modulacji, pedał i zmiany programu tak samo jak sprzęt.",
                             "Play. The instrument takes notes, modulation wheel, pedal and program changes just like the hardware.")),
                ]),
                HelpSection(title: tr("Panel", "Front panel"), items: [
                    .note(tr("Wszystko stoi tam, gdzie na prawdziwym D-70 – przyciski, cztery suwaki Tone Palette, pokrętło VALUE. Kto zna sprzęt, nie musi się niczego uczyć.",
                             "Everything is where it is on a real D-70 – the buttons, the four Tone Palette sliders, the VALUE dial. If you know the hardware, there is nothing new to learn.")),
                    .bullet(tr("**Wyświetlacz** pokazuje prawdziwe piksele rysowane przez firmware, pomalowane kolorem serii. To jest krój D-70 co do piksela, nie podróbka.",
                               "The **display** shows the real pixels drawn by the firmware, painted in the series colour. This is the D-70 typeface down to the pixel, not an imitation.")),
                    .bullet(tr("**Brzmienie** wybierasz tak jak na sprzęcie: **Performance** albo **Patch**, potem **bank**, potem **numer**.",
                               "**Choose a sound** the way you do on the hardware: **Performance** or **Patch**, then **bank**, then **number**.")),
                    .bullet(tr("**Suwaki Tone Palette** (Lower 1, Lower 2, Upper 3, Upper 4) ciągniesz myszą. **Pokrętło VALUE** kręcisz myszą dookoła, a w jego lewą i prawą połowę możesz klikać.",
                               "**Tone Palette sliders** (Lower 1, Lower 2, Upper 3, Upper 4) are dragged with the mouse. The **VALUE dial** is turned by dragging around it, and you can click its left and right halves.")),
                    .bullet(tr("**Diody na przyciskach** świecą kolorem akcentu serii – stan bierze się wprost z firmware'u i nadąża za zmianą trybu, tak jak w sprzęcie.",
                               "The **LEDs on the buttons** glow in the series accent colour – their state comes straight from the firmware and follows mode changes, just like the hardware.")),
                    .bullet(tr("**Pokrętło VALUE i przyciski INC/DEC** zmieniają wartości tak jak na sprzęcie – tym wchodzisz w ustawienia instrumentu i je przestawiasz.",
                               "**The VALUE dial and the INC/DEC buttons** change values just like on the hardware – this is how you go into the instrument's settings and adjust them.")),
                ]),
                HelpSection(title: tr("MIDI learn", "MIDI learn"), items: [
                    .note(tr("Tego na prawdziwym D-70 nie ma: możesz przypisać gałki i suwaki swojego kontrolera do elementów panelu.",
                             "This is not on a real D-70: you can map the knobs and sliders of your controller to panel controls.")),
                    .step(tr("Naciśnij **LEARN** w lewym górnym rogu panelu. Wszystkie elementy, które można przypisać, dostaną złoty obrys.",
                             "Press **LEARN** in the top left corner of the panel. Every control you can map gets a golden outline.")),
                    .step(tr("Kliknij element – na przykład suwak numer 1. Obrys zrobi się mocniejszy, a element się rozświetli: instrument czeka właśnie na niego.",
                             "Click a control – slider 1, say. Its outline gets stronger and the control lights up: this is what the instrument is waiting for.")),
                    .step(tr("Rusz gałką albo suwakiem na kontrolerze. Przypisanie gotowe. Powtarzaj dla kolejnych elementów.",
                             "Move a knob or slider on your controller. The mapping is done. Repeat for the next control.")),
                    .step(tr("Żeby usunąć przypisanie, wskaż element i naciśnij **CLEAR**. Powtórne naciśnięcie **LEARN** kończy uczenie. Przypisania zostają zapamiętane.",
                             "To remove a mapping, select the control and press **CLEAR**. Pressing **LEARN** again ends learning. Mappings are remembered.")),
                    .note(tr("**Gałka przejmuje suwak dopiero po dojechaniu.** Przypisana gałka nie rusza instrumentem, dopóki nie dokręcisz jej do wartości, którą suwak ma w tej chwili. Dzięki temu brzmienie nie skacze przy pierwszym drgnięciu i nie psują go komunikacje, które programy rozsyłają same z siebie. Po przestawieniu suwaka myszą gałka musi dojechać od nowa.",
                             "**A knob takes over only once it catches up.** An assigned knob does not move the instrument until you turn it to the value the slider currently has. That way the sound does not jump at the first touch, and messages that programs send on their own cannot spoil it. After you move a slider with the mouse, the knob has to catch up again.")),
                    .bullet(tr("Przy wyborze numeru kontrolera omijaj **CC 0** (Bank Select) i **CC 1** (kółko modulacji) – te rozsyłają programy i DAW-y z własnej inicjatywy. Bezpieczne są na przykład **CC 20–23** albo **CC 70–73**.",
                               "When choosing a controller number avoid **CC 0** (Bank Select) and **CC 1** (modulation wheel) – programs and DAWs send those on their own. Safe choices are, for example, **CC 20–23** or **CC 70–73**.")),
                ]),
                HelpSection(title: tr("Audio i MIDI (tylko program)", "Audio and MIDI (app only)"), items: [
                    .note(tr("We wtyczce tego okna nie ma i nie jest potrzebne: kartę, częstotliwość i wielkość bufora podaje DAW.",
                             "The plug-in has no such window and does not need one: the DAW provides the device, sample rate and buffer size.")),
                    .bullet(tr("**Wyjście** – karta, na którą idzie dźwięk. **Częstotliwość** – spośród tych, które karta naprawdę obsługuje.",
                               "**Output** – the device the sound goes to. **Sample rate** – from those the device actually supports.")),
                    .bullet(tr("**Bufor** – im mniejszy, tym mniejsze opóźnienie, ale tym łatwiej o trzaski. Na dole okna widać wyliczone opóźnienie w milisekundach. Przy 64 próbkach bywa ciasno – jeśli coś trzeszczy, podnieś do 128 albo 256.",
                               "**Buffer** – the smaller it is, the lower the latency, but the easier it is to get glitches. The window shows the resulting latency in milliseconds. 64 samples can be tight – if you hear crackles, raise it to 128 or 256.")),
                    .bullet(tr("**Wejście MIDI** – jedno urządzenie albo wszystkie naraz. Urządzenie wpięte później program wykryje sam.",
                               "**MIDI input** – one device or all of them. A device plugged in later is picked up automatically.")),
                ]),
                HelpSection(title: tr("Czego jeszcze nie ma", "Not there yet"), items: [
                    .bullet(tr("**Zgranie offline (bounce) daje ciszę** – instrument liczy dźwięk w tempie czasu rzeczywistego, a zgranie leci szybciej. Nagraj ścieżkę na żywo.",
                               "**Offline bounce comes out silent** – the instrument runs in real time while a bounce runs faster. Record the track live instead.")),
                    .bullet(tr("**Rozruch trwa około 20 sekund** – tyle potrzebuje firmware.",
                               "**Starting takes about 20 seconds** – that is how long the firmware needs.")),
                ]),
                HelpSection(title: tr("Dobrze wiedzieć", "Good to know"), items: [
                    .bullet(tr("Instrument liczy dźwięk w **32 kHz**, tak jak prawdziwy D-70, i przelicza go na częstotliwość karty albo projektu. Brzmienie jest takie samo jak w sprzęcie – sprawdzone nuta po nucie.",
                               "The instrument runs at **32 kHz**, like a real D-70, and resamples to the device or project rate. The sound is identical to the hardware – checked note by note.")),
                    .bullet(tr("Każda wstawiona wtyczka ma **własny instrument**, więc wstawienie kolejnej nie zabiera brzmień poprzedniej.",
                               "Every plug-in instance has its **own instrument**, so adding another does not take sounds away from the first.")),
                    .bullet(tr("**Pamięć brzmień zostaje.** Co zmienisz i zapiszesz w instrumencie, znajdziesz tam po ponownym otwarciu – tak jak w sprzęcie. Pamięć jest jedna, wspólna: masz jeden D-70, nie cztery.",
                               "**The patch memory persists.** Whatever you change and save in the instrument is there when you open it again – just like the hardware. There is one shared memory: you own one D-70, not four.")),
                    .bullet(tr("Gdy grają **dwie kopie naraz**, pamięć bierze ta uruchomiona jako pierwsza – i tylko ona zapisuje zmiany. Druga gra tymi samymi brzmieniami, ale nic nie nadpisze.",
                               "When **two copies run at once**, the one started first owns the memory – and only it saves changes. The second plays the same sounds but overwrites nothing.")),
                ]),
                HelpSection(title: tr("Wersja testowa – napisz do mnie", "Beta version – please write to me"), items: [
                    .note(tr("To jest **wersja testowa (beta)**. Instrument jest dopracowany i gra, ale każdy komputer, każda karta i każdy egzemplarz D-70 są inne. Jeśli coś nie działa, czegoś brakuje albo masz pomysł – napisz. Każda wiadomość pomaga.",
                             "This is a **beta version**. The instrument is polished and plays, but every computer, every audio device and every D-70 is different. If something does not work, something is missing or you have an idea – please write. Every message helps.")),
                    .bullet(tr("W programie: menu **Pomoc → Zgłoś błąd lub pomysł…**. Otworzy się gotowy e-mail z wersją programu, systemem i tym, jakie oprogramowanie D-70 masz u siebie. Możesz te dane usunąć przed wysłaniem.",
                               "In the app: **Help → Report a Problem or Idea…**. It opens a ready-made e-mail with the app version, your system and which D-70 software you have. You may delete that information before sending.")),
                    .bullet(tr("Program **niczego nie wysyła sam** i nie sprawdza niczego w sieci – to zwykły e-mail, który wysyłasz Ty. Adres: **kontakt@bronislawhonca.pl**.",
                               "The app **never sends anything by itself** and checks nothing online – it is a plain e-mail that you send. Address: **kontakt@bronislawhonca.pl**.")),
                ]),
                HelpSection(title: tr("Licencja", "Licence"), items: [
                    .note(tr("Silnik BHD-70 korzysta z emulacji układów na licencji **GPL-3.0**. Dlatego BHD-70 jest darmowy i rozdawany razem z kodem źródłowym.",
                             "The BHD-70 engine uses chip emulation under the **GPL-3.0** licence. That is why BHD-70 is free and comes with its source code.")),
                    .note(tr("**Roland D-70** to nazwa i instrument firmy Roland. BHD-70 nie jest programem Rolanda, nie jest przez Roland wydany ani zatwierdzony. Firmware i brzmienia D-70 są własnością Rolanda i **nie są częścią BHD-70** – żeby instrument zagrał, trzeba mieć własny D-70 i zgrać je z niego.",
                             "**Roland D-70** is the name of an instrument made by Roland. BHD-70 is not Roland software and is neither released nor endorsed by Roland. The D-70 firmware and sounds are Roland's property and are **not part of BHD-70** – to make the instrument play you need your own D-70 and a dump taken from it.")),
                    .note(tr("Podziękowania dla kolegów z **Sojus Records** za inspirację: to oni zbudowali wtyczkę z emulacją Ensoniq SD-1 i pokazali, że tą drogą można przywrócić do życia instrument, którego nikt wcześniej nie emulował.",
                             "Thanks to the folks at **Sojus Records** for the inspiration: they built a plug-in around an Ensoniq SD-1 emulation and showed that an instrument nobody had emulated before can be brought back this way.")),
                    .note(tr("Jedyna kość, którą BHD-70 nosi w sobie, to **krój pisma wyświetlacza** – i ta nie jest Rolanda: oryginału nikt nigdy nie zgrał, więc jest dorobiony.",
                             "The only chip image inside BHD-70 is the **display font** – and that one is not Roland's: the original has never been dumped, so it is a substitute.")),
                ]),
            ])
    }
}
